"""LaTeX paper skeleton generator with figure injection and a mocked prose generator.

Conceptual references:
- ./docs/en.md (this lesson)
- Phase 19 lessons 50-53 (earlier auto-research stages)

Stdlib only. Run: python3 code/main.py
"""

from __future__ import annotations

import json
import os
import re
from dataclasses import dataclass, field
from typing import Callable, Iterable


class PaperValidationError(Exception):
    """Raised when the paper fails a structural gate before render."""


@dataclass
class BibEntry:
    key: str
    entry_type: str
    fields: dict

    def to_bibtex(self) -> str:
        lines = [f"@{self.entry_type}{{{self.key},"]
        for k, v in sorted(self.fields.items()):
            safe = str(v).replace("{", "").replace("}", "")
            lines.append(f"  {k} = {{{safe}}},")
        lines.append("}")
        return "\n".join(lines)


@dataclass
class Figure:
    id: str
    path: str
    caption: str
    width: str = "0.8\\textwidth"

    @property
    def label(self) -> str:
        return f"fig:{self.id}"


@dataclass
class Section:
    id: str
    title: str
    body: str = ""
    cites: list[str] = field(default_factory=list)
    figure_refs: list[str] = field(default_factory=list)

    @property
    def label(self) -> str:
        return f"sec:{self.id}"


@dataclass
class Paper:
    title: str
    authors: list[str]
    abstract: str
    sections: list[Section] = field(default_factory=list)
    figures: list[Figure] = field(default_factory=list)
    bibliography: list[BibEntry] = field(default_factory=list)


ProseGenerator = Callable[[Section, Paper], str]


def _validate(paper: Paper) -> None:
    if not paper.title.strip():
        raise PaperValidationError("title is empty")
    if not paper.abstract.strip():
        raise PaperValidationError("abstract is empty")

    fig_ids: set[str] = set()
    for fig in paper.figures:
        if fig.id in fig_ids:
            raise PaperValidationError(f"duplicate figure id: {fig.id}")
        fig_ids.add(fig.id)

    bib_keys: set[str] = set()
    for b in paper.bibliography:
        if b.key in bib_keys:
            raise PaperValidationError(f"duplicate bibliography key: {b.key}")
        bib_keys.add(b.key)
    for sec in paper.sections:
        for key in sec.cites:
            if key not in bib_keys:
                raise PaperValidationError(
                    f"section {sec.id!r} cites unknown bibliography key {key!r}"
                )
        for fid in sec.figure_refs:
            if fid not in fig_ids:
                raise PaperValidationError(
                    f"section {sec.id!r} references unknown figure id {fid!r}"
                )


def _escape_latex(text: str) -> str:
    repl = {
        "\\": r"\textbackslash{}",
        "&": r"\&",
        "%": r"\%",
        "$": r"\$",
        "#": r"\#",
        "_": r"\_",
        "{": r"\{",
        "}": r"\}",
        "~": r"\textasciitilde{}",
        "^": r"\textasciicircum{}",
    }
    out_chars: list[str] = []
    for ch in text:
        out_chars.append(repl.get(ch, ch))
    return "".join(out_chars)


def render_latex(paper: Paper) -> str:
    """Render a Paper to a full LaTeX document string."""
    _validate(paper)

    lines: list[str] = []
    lines.append("\\documentclass{article}")
    lines.append("\\usepackage{graphicx}")
    lines.append("\\usepackage{hyperref}")
    lines.append("\\title{" + _escape_latex(paper.title) + "}")
    lines.append("\\author{" + " \\and ".join(_escape_latex(a) for a in paper.authors) + "}")
    lines.append("\\begin{document}")
    lines.append("\\maketitle")
    lines.append("\\begin{abstract}")
    lines.append(_escape_latex(paper.abstract))
    lines.append("\\end{abstract}")

    for sec in paper.sections:
        lines.append("\\section{" + _escape_latex(sec.title) + "}")
        lines.append("\\label{" + sec.label + "}")
        lines.append(sec.body if sec.body else "% body pending")
        for fid in sec.figure_refs:
            lines.append("See Figure~\\ref{fig:" + fid + "}.")
        for cite in sec.cites:
            lines.append("See~\\cite{" + cite + "}.")

    for fig in paper.figures:
        lines.append("\\begin{figure}")
        lines.append("\\centering")
        lines.append("\\includegraphics[width=" + fig.width + "]{" + fig.path + "}")
        lines.append("\\caption{" + _escape_latex(fig.caption) + "}")
        lines.append("\\label{" + fig.label + "}")
        lines.append("\\end{figure}")

    if paper.bibliography:
        lines.append("\\bibliographystyle{plain}")
        lines.append("\\bibliography{references}")

    lines.append("\\end{document}")
    return "\n".join(lines) + "\n"


def render_bibtex(paper: Paper) -> str:
    return "\n\n".join(b.to_bibtex() for b in paper.bibliography) + ("\n" if paper.bibliography else "")


class MockProseGenerator:
    """Deterministic prose generator. Substitutes for a model in tests and demos."""

    def __init__(self, outlines: dict[str, str]) -> None:
        self.outlines = outlines

    def __call__(self, section: Section, paper: Paper) -> str:
        seed = self.outlines.get(section.id, section.title)
        first = f"In this section we discuss {section.title.lower()}: {seed}."
        bits: list[str] = []
        for fid in section.figure_refs:
            bits.append(f"Figure~\\ref{{fig:{fid}}} shows the relevant artifact.")
        for c in section.cites:
            bits.append(f"This builds on prior work~\\cite{{{c}}}.")
        second = " ".join(bits) if bits else "We discuss implications below."
        return first + "\n\n" + second


def read_experiment_manifest(manifests: Iterable[dict], paper_dir: str) -> list[Figure]:
    """Convert experiment output manifests into Figure records.

    Each manifest is expected to be a dict of shape:
        {"name": str, "artifacts": [{"path": str, "caption": str}, ...]}
    Paths in artifacts may be absolute or relative to the manifest's cwd; we
    normalise them relative to paper_dir.
    """
    figs: list[Figure] = []
    counter = 0
    for m in manifests:
        name = m.get("name", "exp")
        artifacts = m.get("artifacts", [])
        for art in artifacts:
            path = art.get("path", "")
            caption = art.get("caption", "")
            if not path:
                continue
            counter += 1
            try:
                rel = os.path.relpath(path, paper_dir)
            except ValueError:
                rel = path
            fid = re.sub(r"[^a-zA-Z0-9]+", "-", f"{name}-{counter}").strip("-").lower()
            figs.append(Figure(id=fid, path=rel, caption=caption or name))
    return figs


@dataclass
class PaperWriter:
    prose: ProseGenerator

    def fill_prose(self, paper: Paper) -> Paper:
        for sec in paper.sections:
            if not sec.body:
                sec.body = self.prose(sec, paper)
        return paper

    def write(self, paper: Paper, out_dir: str) -> dict:
        """Validate, fill prose, render, and write three files. Returns the manifest dict."""
        os.makedirs(out_dir, exist_ok=True)
        self.fill_prose(paper)
        tex = render_latex(paper)
        bib = render_bibtex(paper)

        tex_path = os.path.join(out_dir, "paper.tex")
        bib_path = os.path.join(out_dir, "references.bib")
        man_path = os.path.join(out_dir, "manifest.json")

        with open(tex_path, "w", encoding="utf-8") as f:
            f.write(tex)
        with open(bib_path, "w", encoding="utf-8") as f:
            f.write(bib)

        manifest = {
            "title": paper.title,
            "authors": list(paper.authors),
            "sections": [
                {"id": s.id, "title": s.title, "cites": list(s.cites),
                 "figure_refs": list(s.figure_refs), "body_chars": len(s.body)}
                for s in paper.sections
            ],
            "figures": [
                {"id": f.id, "path": f.path, "caption": f.caption, "label": f.label}
                for f in paper.figures
            ],
            "bibliography": [b.key for b in paper.bibliography],
            "tex_path": tex_path,
            "bib_path": bib_path,
        }
        with open(man_path, "w", encoding="utf-8") as f:
            json.dump(manifest, f, indent=2, sort_keys=True)
        return manifest


def demo(out_dir: str | None = None) -> dict:
    """Self-contained demo. Builds a small paper from two mocked experiments.

    Writes into a temp directory by default so the worktree stays clean.
    """
    import tempfile as _tempfile
    if out_dir is None:
        out_dir = _tempfile.mkdtemp(prefix="paper-writer-demo-")
    experiments = [
        {"name": "loss-curve", "artifacts": [
            {"path": "figs/loss.pdf", "caption": "Training loss across epochs"},
        ]},
        {"name": "ablation", "artifacts": [
            {"path": "figs/ablation.pdf", "caption": "Ablation over decoder width"},
        ]},
    ]
    figs = read_experiment_manifest(experiments, out_dir)
    paper = Paper(
        title="Auto-Research Loop: Empirical Notes",
        authors=["Lab Bot"],
        abstract="We describe a small experiment harness that emits LaTeX from structured outputs.",
        sections=[
            Section(id="intro", title="Introduction", cites=["smith2020"],
                    figure_refs=[]),
            Section(id="method", title="Method", cites=["jones2021"],
                    figure_refs=[figs[0].id]),
            Section(id="results", title="Results", cites=[],
                    figure_refs=[figs[1].id]),
        ],
        figures=figs,
        bibliography=[
            BibEntry(key="smith2020", entry_type="article",
                     fields={"title": "On harnesses", "author": "Smith", "year": "2020"}),
            BibEntry(key="jones2021", entry_type="article",
                     fields={"title": "On loops", "author": "Jones", "year": "2021"}),
        ],
    )
    prose = MockProseGenerator(outlines={
        "intro": "we motivate the auto-research loop",
        "method": "we describe the skeleton-first writer",
        "results": "we present two ablations",
    })
    writer = PaperWriter(prose=prose)
    return writer.write(paper, out_dir)


if __name__ == "__main__":
    manifest = demo()
    print(json.dumps({
        "sections": len(manifest["sections"]),
        "figures": len(manifest["figures"]),
        "bib_keys": manifest["bibliography"],
        "tex_path": manifest["tex_path"],
    }, indent=2))

// Lesson: Paper Writer (phase 19 / lesson 54)
// TypeScript port of code/main.py. Node standard library only.
// Source: phases/19-capstone-projects/54-paper-writer/docs/en.md
// Run: npx tsx phases/19-capstone-projects/54-paper-writer/code/main.ts

import { mkdirSync, mkdtempSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, relative } from "node:path";

export class PyFloat {
  constructor(readonly v: number) {}
}

export type Json = null | boolean | number | string | PyFloat | Json[] | { [key: string]: Json };
export type Obj = { [key: string]: Json };

function pyFloatRepr(x: number): string {
  if (Number.isNaN(x)) return "NaN";
  if (!Number.isFinite(x)) return x > 0 ? "Infinity" : "-Infinity";
  if (x === 0) return Object.is(x, -0) ? "-0.0" : "0.0";
  const [mant, expStr] = x.toExponential().split("e");
  const exp = Number(expStr);
  const neg = mant.startsWith("-");
  const digits = mant.replace("-", "").replace(".", "");
  let body: string;
  if (exp < -4 || exp >= 16) {
    const frac = digits.length > 1 ? "." + digits.slice(1) : "";
    body = digits[0] + frac + "e" + (exp < 0 ? "-" : "+") + String(Math.abs(exp)).padStart(2, "0");
  } else if (exp < 0) {
    body = "0." + "0".repeat(-exp - 1) + digits;
  } else if (digits.length <= exp + 1) {
    body = digits + "0".repeat(exp + 1 - digits.length) + ".0";
  } else {
    body = digits.slice(0, exp + 1) + "." + digits.slice(exp + 1);
  }
  return (neg ? "-" : "") + body;
}

function jsonStr(s: string): string {
  return (
    '"' +
    s.replace(/[\\"\u0000-\u001f\u007f-￿]/g, (c) => {
      if (c === '"') return '\\"';
      if (c === "\\") return "\\\\";
      if (c === "\n") return "\\n";
      if (c === "\r") return "\\r";
      if (c === "\t") return "\\t";
      if (c === "\b") return "\\b";
      if (c === "\f") return "\\f";
      return "\\u" + c.charCodeAt(0).toString(16).padStart(4, "0");
    }) +
    '"'
  );
}

function pyDumps(v: Json, indent: number | null = null, level = 0): string {
  if (v === null) return "null";
  if (v === true) return "true";
  if (v === false) return "false";
  if (v instanceof PyFloat) return pyFloatRepr(v.v);
  if (typeof v === "number") return Number.isInteger(v) ? String(v) : pyFloatRepr(v);
  if (typeof v === "string") return jsonStr(v);
  let open: string;
  let close: string;
  let items: string[];
  if (Array.isArray(v)) {
    if (v.length === 0) return "[]";
    open = "[";
    close = "]";
    items = v.map((x) => pyDumps(x, indent, level + 1));
  } else {
    const keys = Object.keys(v);
    if (keys.length === 0) return "{}";
    open = "{";
    close = "}";
    items = keys.map((k) => jsonStr(k) + ": " + pyDumps(v[k], indent, level + 1));
  }
  if (indent === null) return open + items.join(", ") + close;
  const pad = "\n" + " ".repeat(indent * (level + 1));
  return open + pad + items.join("," + pad) + "\n" + " ".repeat(indent * level) + close;
}

function pyStrRepr(s: string): string {
  const quote = s.includes("'") && !s.includes('"') ? '"' : "'";
  return quote + s.replace(/\\/g, "\\\\").replace(new RegExp(quote, "g"), "\\" + quote) + quote;
}

function sortKeysDeep(v: Json): Json {
  if (Array.isArray(v)) return v.map(sortKeysDeep);
  if (v !== null && typeof v === "object" && !(v instanceof PyFloat)) {
    const out: Obj = {};
    for (const k of Object.keys(v).sort()) out[k] = sortKeysDeep(v[k]);
    return out;
  }
  return v;
}

export class PaperValidationError extends Error {}

export class BibEntry {
  constructor(
    public key: string,
    public entry_type: string,
    public fields: Record<string, string>,
  ) {}

  toBibtex(): string {
    const lines = [`@${this.entry_type}{${this.key},`];
    for (const k of Object.keys(this.fields).sort()) {
      const safe = String(this.fields[k]).replace(/\{/g, "").replace(/\}/g, "");
      lines.push(`  ${k} = {${safe}},`);
    }
    lines.push("}");
    return lines.join("\n");
  }
}

export class Figure {
  constructor(
    public id: string,
    public path: string,
    public caption: string,
    public width = "0.8\\textwidth",
  ) {}

  get label(): string {
    return `fig:${this.id}`;
  }
}

export class Section {
  constructor(
    public id: string,
    public title: string,
    public body = "",
    public cites: string[] = [],
    public figure_refs: string[] = [],
  ) {}

  get label(): string {
    return `sec:${this.id}`;
  }
}

export class Paper {
  constructor(
    public title: string,
    public authors: string[],
    public abstract: string,
    public sections: Section[] = [],
    public figures: Figure[] = [],
    public bibliography: BibEntry[] = [],
  ) {}
}

type ProseGenerator = (section: Section, paper: Paper) => string;

function validate(paper: Paper): void {
  if (!paper.title.trim()) throw new PaperValidationError("title is empty");
  if (!paper.abstract.trim()) throw new PaperValidationError("abstract is empty");

  const figIds = new Set<string>();
  for (const fig of paper.figures) {
    if (figIds.has(fig.id)) throw new PaperValidationError(`duplicate figure id: ${fig.id}`);
    figIds.add(fig.id);
  }

  const bibKeys = new Set<string>();
  for (const b of paper.bibliography) {
    if (bibKeys.has(b.key)) throw new PaperValidationError(`duplicate bibliography key: ${b.key}`);
    bibKeys.add(b.key);
  }
  for (const sec of paper.sections) {
    for (const key of sec.cites) {
      if (!bibKeys.has(key)) {
        throw new PaperValidationError(`section ${pyStrRepr(sec.id)} cites unknown bibliography key ${pyStrRepr(key)}`);
      }
    }
    for (const fid of sec.figure_refs) {
      if (!figIds.has(fid)) {
        throw new PaperValidationError(`section ${pyStrRepr(sec.id)} references unknown figure id ${pyStrRepr(fid)}`);
      }
    }
  }
}

const LATEX_REPL: Record<string, string> = {
  "\\": "\\textbackslash{}",
  "&": "\\&",
  "%": "\\%",
  $: "\\$",
  "#": "\\#",
  _: "\\_",
  "{": "\\{",
  "}": "\\}",
  "~": "\\textasciitilde{}",
  "^": "\\textasciicircum{}",
};

function escapeLatex(text: string): string {
  const outChars: string[] = [];
  for (const ch of text) outChars.push(LATEX_REPL[ch] ?? ch);
  return outChars.join("");
}

function renderLatex(paper: Paper): string {
  validate(paper);

  const lines: string[] = [];
  lines.push("\\documentclass{article}");
  lines.push("\\usepackage{graphicx}");
  lines.push("\\usepackage{hyperref}");
  lines.push("\\title{" + escapeLatex(paper.title) + "}");
  lines.push("\\author{" + paper.authors.map(escapeLatex).join(" \\and ") + "}");
  lines.push("\\begin{document}");
  lines.push("\\maketitle");
  lines.push("\\begin{abstract}");
  lines.push(escapeLatex(paper.abstract));
  lines.push("\\end{abstract}");

  for (const sec of paper.sections) {
    lines.push("\\section{" + escapeLatex(sec.title) + "}");
    lines.push("\\label{" + sec.label + "}");
    lines.push(sec.body ? sec.body : "% body pending");
    for (const fid of sec.figure_refs) lines.push("See Figure~\\ref{fig:" + fid + "}.");
    for (const cite of sec.cites) lines.push("See~\\cite{" + cite + "}.");
  }

  for (const fig of paper.figures) {
    lines.push("\\begin{figure}");
    lines.push("\\centering");
    lines.push("\\includegraphics[width=" + fig.width + "]{" + fig.path + "}");
    lines.push("\\caption{" + escapeLatex(fig.caption) + "}");
    lines.push("\\label{" + fig.label + "}");
    lines.push("\\end{figure}");
  }

  if (paper.bibliography.length) {
    lines.push("\\bibliographystyle{plain}");
    lines.push("\\bibliography{references}");
  }

  lines.push("\\end{document}");
  return lines.join("\n") + "\n";
}

function renderBibtex(paper: Paper): string {
  return paper.bibliography.map((b) => b.toBibtex()).join("\n\n") + (paper.bibliography.length ? "\n" : "");
}

export class MockProseGenerator {
  constructor(public outlines: Record<string, string>) {}

  call(section: Section, _paper: Paper): string {
    const seed = Object.hasOwn(this.outlines, section.id) ? this.outlines[section.id] : section.title;
    const first = `In this section we discuss ${section.title.toLowerCase()}: ${seed}.`;
    const bits: string[] = [];
    for (const fid of section.figure_refs) bits.push(`Figure~\\ref{fig:${fid}} shows the relevant artifact.`);
    for (const c of section.cites) bits.push(`This builds on prior work~\\cite{${c}}.`);
    const second = bits.length ? bits.join(" ") : "We discuss implications below.";
    return first + "\n\n" + second;
  }

  asGenerator(): ProseGenerator {
    return (section, paper) => this.call(section, paper);
  }
}

interface Artifact {
  path?: string;
  caption?: string;
}

interface Manifest {
  name?: string;
  artifacts?: Artifact[];
}

function readExperimentManifest(manifests: Manifest[], paperDir: string): Figure[] {
  const figs: Figure[] = [];
  let counter = 0;
  for (const m of manifests) {
    const name = m.name ?? "exp";
    const artifacts = m.artifacts ?? [];
    for (const art of artifacts) {
      const path = art.path ?? "";
      const caption = art.caption ?? "";
      if (!path) continue;
      counter += 1;
      const rel = relative(paperDir, path) || ".";
      const fid = `${name}-${counter}`
        .replace(/[^a-zA-Z0-9]+/g, "-")
        .replace(/^-+|-+$/g, "")
        .toLowerCase();
      figs.push(new Figure(fid, rel, caption || name));
    }
  }
  return figs;
}

export class PaperWriter {
  constructor(public prose: ProseGenerator) {}

  fillProse(paper: Paper): Paper {
    for (const sec of paper.sections) {
      if (!sec.body) sec.body = this.prose(sec, paper);
    }
    return paper;
  }

  write(paper: Paper, outDir: string): Obj {
    mkdirSync(outDir, { recursive: true });
    this.fillProse(paper);
    const tex = renderLatex(paper);
    const bib = renderBibtex(paper);

    const texPath = join(outDir, "paper.tex");
    const bibPath = join(outDir, "references.bib");
    const manPath = join(outDir, "manifest.json");

    writeFileSync(texPath, tex, "utf-8");
    writeFileSync(bibPath, bib, "utf-8");

    const manifest: Obj = {
      title: paper.title,
      authors: [...paper.authors],
      sections: paper.sections.map((s) => ({
        id: s.id,
        title: s.title,
        cites: [...s.cites],
        figure_refs: [...s.figure_refs],
        body_chars: [...s.body].length,
      })),
      figures: paper.figures.map((f) => ({ id: f.id, path: f.path, caption: f.caption, label: f.label })),
      bibliography: paper.bibliography.map((b) => b.key),
      tex_path: texPath,
      bib_path: bibPath,
    };
    writeFileSync(manPath, pyDumps(sortKeysDeep(manifest), 2), "utf-8");
    return manifest;
  }
}

function demo(outDir: string | null = null): Obj {
  const dir = outDir ?? mkdtempSync(join(tmpdir(), "paper-writer-demo-"));
  const experiments: Manifest[] = [
    { name: "loss-curve", artifacts: [{ path: "figs/loss.pdf", caption: "Training loss across epochs" }] },
    { name: "ablation", artifacts: [{ path: "figs/ablation.pdf", caption: "Ablation over decoder width" }] },
  ];
  const figs = readExperimentManifest(experiments, dir);
  const paper = new Paper(
    "Auto-Research Loop: Empirical Notes",
    ["Lab Bot"],
    "We describe a small experiment harness that emits LaTeX from structured outputs.",
    [
      new Section("intro", "Introduction", "", ["smith2020"], []),
      new Section("method", "Method", "", ["jones2021"], [figs[0].id]),
      new Section("results", "Results", "", [], [figs[1].id]),
    ],
    figs,
    [
      new BibEntry("smith2020", "article", { title: "On harnesses", author: "Smith", year: "2020" }),
      new BibEntry("jones2021", "article", { title: "On loops", author: "Jones", year: "2021" }),
    ],
  );
  const prose = new MockProseGenerator({
    intro: "we motivate the auto-research loop",
    method: "we describe the skeleton-first writer",
    results: "we present two ablations",
  });
  const writer = new PaperWriter(prose.asGenerator());
  return writer.write(paper, dir);
}

if (require.main === module) {
  const manifest = demo();
  console.log(
    pyDumps(
      {
        sections: (manifest["sections"] as Json[]).length,
        figures: (manifest["figures"] as Json[]).length,
        bib_keys: manifest["bibliography"],
        tex_path: manifest["tex_path"],
      },
      2,
    ),
  );
}
